# JavaScript Function to Compute Average from DataFrame

```javascript
const dataForge = require('data-forge');

/**
 * Compute the average of values in a tabular dataset for specified rows and columns
 * @param {Object} dataframe - A data-forge DataFrame object
 * @param {Array<number>} rows - Array of row indices to include in calculation
 * @param {Array<string>} columns - Array of column names to include in calculation
 * @returns {number} The average of all specified values
 */
function computeAverage(dataframe, rows, columns) {
  // Filter the dataframe to include only specified rows
  const filteredByRows = dataframe
    .where((row, index) => rows.includes(index));

  // Select only the specified columns
  const filteredByColumns = filteredByRows
    .select(columns);

  // Flatten all values and compute the average
  let sum = 0;
  let count = 0;

  filteredByColumns.forEach((row) => {
    columns.forEach((col) => {
      const value = row[col];
      if (typeof value === 'number') {
        sum += value;
        count += 1;
      }
    });
  });

  return count > 0 ? sum / count : 0;
}

// Example usage:
const df = new dataForge.DataFrame({
  columnNames: ['A', 'B', 'C', 'D'],
  rows: [
    { A: 10, B: 20, C: 30, D: 40 },
    { A: 15, B: 25, C: 35, D: 45 },
    { A: 20, B: 30, C: 40, D: 50 },
    { A: 25, B: 35, C: 45, D: 55 }
