```javascript
const { from } = require('rxjs');
const { map, filter } = require('rxjs/operators');

/**
 * Given an input list of characters, produce a list containing only 
 * the characters that immediately follow each slash symbol.
 * 
 * @param {string[]} characters - Array of characters
 * @returns {Promise<string[]>} Promise resolving to array of characters after slashes
 */
function extractCharactersAfterSlashes(characters) {
  return new Promise((resolve, reject) => {
    const result = [];

    from(characters)
      .pipe(
        // Map each character with its index
        map((char, index) => ({ char, index })),
        // Filter to keep only characters that have a slash before them
        filter(({ char, index }) => 
          index > 0 && characters[index - 1] === '/'
        ),
        // Extract just the character
        map(({ char }) => char)
      )
      .subscribe({
        next: (char) => result.push(char),
        error: (err) => reject(err),
        complete: () => resolve(result)
      });
  });
}

