  const binarized = tf.cast(tf.notEqual(tensor, 0), 'float32');

  // Convert back to array if input was an array
  if (!isTensor) {
    const result = binarized.arraySync();
    binarized.dispose();
    if (tensor !== data) tensor.dispose();
    return result;
  }

  return binarized;
}

