/**
 * Calculates the sum of outer products of corresponding vectors from two sequences
 * @param {number[][]} sequence1 - First sequence of numeric lists
 * @param {number[][]} sequence2 - Second sequence of numeric lists
 * @returns {Matrix} - The sum of all outer products
 */
function sumOfOuterProducts(sequence1, sequence2) {
  if (sequence1.length !== sequence2.length) {
    throw new Error('Sequences must have equal length');
  }

  if (sequence1.length === 0) {
    throw new Error('Sequences cannot be empty');
  }

  // Determine the dimensions from the first vectors
  const rows = sequence1[0].length;
  const cols = sequence2[0].length;

  // Initialize result matrix with zeros
  let resultMatrix = new Matrix(rows, cols);

  // Calculate the sum of outer products
  for (let i = 0; i < sequence1.length; i++) {
    const vector1 = sequence1[i];
    const vector2 = sequence2[i];

    if (vector1.length !== rows || vector2.length !== cols) {
      throw new Error(`All vectors must maintain consistent dimensions (${rows}x${cols})`);
    }

    // Calculate outer product for this pair: vector1 ⊗ vector2
    const outerProduct = new Matrix(rows, cols);
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        outerProduct.set(r, c, vector1[r] * vector2[c]);
      }
    }

    // Add to result
    resultMatrix = resultMatrix.add(outerProduct);
  }

  return resultMatrix;
}

