Here's a self-contained JavaScript function to compute the moving average:

```javascript
function movingAverage(lst0, windowSize) {
    if (windowSize <= 0) {
        throw new Error("Window size must be greater than zero.");
    }
    if (lst0.length < windowSize) {
        throw new Error("List length must be at least as large as the window size.");
    }

    const averages = [];
    for (let i = 0; i <= lst0.length - windowSize; i++) {
        const window = lst0.slice(i, i + windowSize);
        const sum = window.reduce((acc, val) => acc + val, 0);
        const average = sum / windowSize;
        averages.push(average);
    }

    return averages;
}

