```javascript
const ndarray = require('ndarray');
const ops = require('ndarray-ops');

/**
 * Clones an input vector a specified number of times along a given axis.
 * 
 * @param {ndarray} vector - The input vector (1D or nD array)
 * @param {number} times - Number of times to clone the vector
 * @param {number} axis - The axis along which to clone (0, 1, 2, etc.)
 * @returns {ndarray} A new array with the vector cloned along the specified axis
 * 
 * @example
 * const a = ndarray([1, 2, 3]);
 * const result = cloneVectorAlongAxis(a, 3, 0);
 * // result shape: [3, 3]
 * // result data: [1, 2, 3, 1, 2, 3, 1, 2, 3]
 */
function cloneVectorAlongAxis(vector, times, axis) {
  if (times < 1) {
    throw new Error('times must be at least 1');
  }

  if (axis < 0) {
    throw new Error('axis must be non-negative');
  }

  // Get the shape of the input vector
  const inputShape = vector.shape.slice();
  const inputSize = vector.size;

  // Create output shape by inserting the clone dimension at the specified axis
  const outputShape = inputShape.slice();
  if (axis > outputShape.length) {
    throw new Error(`axis ${axis} is out of bounds for array of dimension ${outputShape.length}`);
  }

  outputShape.splice(axis, 0, times);

  // Create output array
  const outputSize = inputSize * times;
  const output = ndarray(new Float64Array(outputSize), outputShape);

  // Clone the vector along the specified axis
  for (let i = 0; i < times; i++) {
    // Create a view of the output at position i along the axis
    const view = output.pick(axis, i);

    // Copy the input vector into this view
    ops.assign(view, vector);
  }

  return output;
}

