    throw new Error('Lists must have the same length');
  }

  if (lst0.length === 0) {
    throw new Error('Lists cannot be empty');
  }

  // Calculate squared differences
  const squaredDifferences = lst0.map((val0, index) => {
    const difference = math.subtract(val0, lst1[index]);
    return math.square(difference);
  });

  // Calculate and return the average
  return math.mean(squaredDifferences);
}

