function updateDataframeFromAnother(df0, df1, columns = null, keyColumn = null) {
  try {
    // Validate inputs
    if (!df0 || !df1 || typeof df0 !== 'object' || typeof df1 !== 'object') {
      throw new Error('Both df0 and df1 must be valid objects');
    }

    // Get the key column (default to first column)
    const df0Columns = Object.keys(df0);
    const df1Columns = Object.keys(df1);

    if (df0Columns.length === 0 || df1Columns.length === 0) {
      throw new Error('DataFrames must contain at least one column');
    }

    keyColumn = keyColumn || df0Columns[0];

    // Validate key column exists in both dataframes
    if (!df0Columns.includes(keyColumn) || !df1Columns.includes(keyColumn)) {
      throw new Error(`Key column "${keyColumn}" not found in one or both dataframes`);
    }

    // Determine which columns to update
    const columnsToUpdate = columns 
      ? columns.filter(col => df0Columns.includes(col) && df1Columns.includes(col))
      : df0Columns.filter(col => col !== keyColumn && df1Columns.includes(col));

    // Create a lookup map from df1 for faster access
    const df1Lookup = {};
    const df1RowCount = df1[df1Columns[0]].length;

    for (let i = 0; i < df1RowCount; i++) {
