# JavaScript Function to Reset Row Index and Convert to Column

```javascript
const initSqlJs = require('sql.js');

/**
 * Resets the row index of a table and converts existing index values into new columns.
 * 
 * @param {Array<Object>} inputData - The input data array with index information
 * @param {string} indexColumnName - The name of the column containing index values (default: 'index')
 * @param {string} newIndexName - The name for the new reset index column (default: 'row_id')
 * @returns {Promise<Array<Object>>} - The transformed data with reset index and old index as column
 */
async function resetRowIndex(inputData, indexColumnName = 'index', newIndexName = 'row_id') {
  try {
    const SQL = await initSqlJs();
    const db = new SQL.Database();

    // Create a table from input data
    const columns = Object.keys(inputData[0]);
    const columnDefs = columns.map(col => `${col} TEXT`).join(', ');

    db.run(`CREATE TABLE original_table (${columnDefs})`);

    // Insert data
    inputData.forEach((row, index) => {
      const values = columns.map(col => `'${String(row[col]).replace(/'/g, "''")}'`).join(', ');
      db.run(`INSERT INTO original_table VALUES (${values})`);
    });

    // Create new table with reset index and old index as column
    db.run(`
      CREATE TABLE reset_table AS
      SELECT 
        ROW_NUMBER() OVER () - 1 as ${newIndexName},
        ${indexColumnName} as original_${indexColumnName},
        *
      FROM original_table
    `);

    // Query the result
    const stmt = db.prepare(`
      SELECT * FROM reset_table
    `);

    const result = [];
    while (stmt.step()) {
      const row = stmt.getAsObject();
      result.push(row);
    }
    stmt.free();

    db.close();
    return result;

  } catch (error) {
    console.error('Error processing data:', error);
    throw error;
  }
}

// Example usage:
async function main() {
  const inputData = [
    { index: 100, name: 'Alice', value: 42 },
    { index: 105, name: 'Bob', value: 38 },
    { index: 103, name: 'Charlie', value: 45 }
  ];

  const result = await resetRowIndex(inputData, 'index', 'row_id');
  console.log('Result:');
  console.log(result);
}

