```javascript
function imputeColumnMeans(data) {
  /**
   * Imputes missing values in a 2D dataset by replacing them with the
   * column mean of non-missing values.
   *
   * @param {Array<Array<number|null|undefined>>} data - 2D array where missing
   *        values are represented as null or undefined
   * @returns {Array<Array<number>>} New dataset with missing values imputed
   */

  if (!data || data.length === 0) {
    return data;
  }

  const numRows = data.length;
  const numCols = data[0].length;

  // Calculate column means
  const columnMeans = [];
  for (let col = 0; col < numCols; col++) {
    const columnValues = [];

    // Extract non-missing values in this column
    for (let row = 0; row < numRows; row++) {
      const value = data[row][col];
      if (value !== null && value !== undefined && !isNaN(value)) {
        columnValues.push(value);
      }
    }

    // Calculate mean using jStat
    const mean = columnValues.length > 0 
      ? jStat.mean(columnValues) 
      : 0; // Default to 0 if all values missing

    columnMeans.push(mean);
  }

  // Create imputed dataset
  const imputedData = [];
  for (let row = 0; row < numRows; row++) {
    const imputedRow = [];
    for (let col = 0; col < numCols; col++) {
      const value = data[row][col];

      // Use original value if not missing, otherwise use column mean
      if (value !== null && value !== undefined && !isNaN(value)) {
        imputedRow.push(value);
      } else {
        imputedRow.push(columnMeans[col]);
      }
    }
    imputedData.push(imputedRow);
  }

  return imputedData;
}
```

