 */
function findSmallestSecondElement(tuples) {
    // Filter out tuples that don't have at least 2 elements or where the second element is NaN
    const filteredTuples = tuples.filter(tuple => {
        return Array.isArray(tuple) &&
               tuple.length >= 2 &&
