    return df0;
  }

  const numRows = df0.length;
  const numCols = df0[0].length;
  const normalized = df0.map(row => [...row]); // Deep copy

  // Process each column independently
  for (let col = 0; col < numCols; col++) {
    // Find min and max values in the current column
    let minVal = normalized[0][col];
    let maxVal = normalized[0][col];

    for (let row = 0; row < numRows; row++) {
      const value = normalized[row][col];
      if (value < minVal) minVal = value;
      if (value > maxVal) maxVal = value;
    }

    // Apply min-max normalization formula: (x - min) / (max - min)
    const range = maxVal - minVal;

    for (let row = 0; row < numRows; row++) {
      if (range === 0) {
        // Handle case where all values in column are identical
        normalized[row][col] = 0;
      } else {
        normalized[row][col] = (normalized[row][col] - minVal) / range;
      }
    }
  }

  return normalized;
}

