```javascript
/**
 * Counts occurrences of each tuple in a sequence with filtering, ordering, and limiting options
 * @param {Array<Array>} sequence - Array of tuples to count
 * @param {Object} options - Configuration options
 * @param {Function} options.filter - Optional filter function to exclude tuples
 * @param {string} options.orderBy - Sort order: 'count-desc', 'count-asc', 'tuple-asc', 'tuple-desc'
 * @param {number} options.limit - Maximum number of results to return
 * @returns {Array<Object>} Array of {tuple, count} objects
 */
function countTuples(sequence, options = {}) {
  const {
    filter = null,
    orderBy = 'count-desc',
    limit = null
  } = options;

  // Convert tuples to string keys for Map (since array equality doesn't work directly)
  const tupleMap = new Map();

  for (const tuple of sequence) {
    // Apply filter if provided
    if (filter && !filter(tuple)) {
      continue;
    }

    // Convert tuple to string key for consistent counting
    const key = JSON.stringify(tuple);
    tupleMap.set(key, (tupleMap.get(key) || 0) + 1);
  }

  // Convert map to array of objects with original tuple format
  let results = Array.from(tupleMap, ([key, count]) => ({
    tuple: JSON.parse(key),
    count: count
  }));

  // Sort results based on orderBy parameter
  results.sort((a, b) => {
    switch (orderBy) {
      case 'count-asc':
        return a.count - b.count;
      case 'count-desc':
        return b.count - a.count;
      case 'tuple-asc':
        return JSON.stringify(a.tuple).localeCompare(JSON.stringify(b.tuple));
      case 'tuple-desc':
        return JSON.stringify(b.tuple).localeCompare(JSON.stringify(a.tuple));
      default:
        return 0;
    }
  });

  // Apply limit if specified
  if (limit && limit > 0) {
    results = results.slice(0, limit);
  }

  return results;
}

