  { id: 1 },
  { id: 2 },
  { id: 1 },
  { id: 1 },
  { id: 2 }
];
console.log(reorderByFrequency(objects));
// Output: [{ id: 1 }, { id: 1 }, { id: 1 }, { id: 2 }, { id: 2 }]

module.exports = reorderByFrequency;
```

