        if (!filter.field) return; // Skip if no field specified

        const dim = dimensions[filter.field];

        if (filter.type === 'range') {
            // Range filter (min and max values)
            if (filter.min !== undefined) {
                dim.filterRange(filter.min, Infinity);
            }
            if (filter.max !== undefined) {
                dim.filterRange(-Infinity, filter.max);
            }
        } else if (filter.type === 'in') {
            // In filter (array of values)
