                return filter.values.includes(d[filter.field]);
            });
        } else if (filter.type === 'notIn') {
            // Not in filter
            dim.filterFunction(function(d) {
                return !filter.values.includes(d[filter.field]);
            });
        } else if (filter.type === 'equals') {
            // Exact match
            dim.filterExact(filter.value);
        } else if (filter.type === 'regex') {
            // Regex match
            dim.filterFunction(function(d) {
                return new RegExp(filter.pattern).test(d[filter.field]);
