# JavaScript Function for Grouping and Summing with AlaSQL

```javascript
function groupAndSum(tableName = 'df0', groupByColumn = 'column_name0') {
  // Ensure AlaSQL is loaded
  if (typeof alasql === 'undefined') {
    throw new Error('AlaSQL library is not loaded');
  }

  // Get the original table to inspect its columns
  const originalData = alasql(`SELECT * FROM ${tableName}`);

  if (!originalData || originalData.length === 0) {
    return [];
  }

  // Get all column names from the first row
  const allColumns = Object.keys(originalData[0]);

  // Filter out the grouping column to get columns to sum
  const columnsToSum = allColumns.filter(col => col !== groupByColumn);

  // Build the SUM expressions for all numeric columns
  const sumExpressions = columnsToSum
    .map(col => `SUM(${col}) AS ${col}`)
    .join(', ');

  // Execute the GROUP BY query
  const query = `
    SELECT 
      ${groupByColumn},
      ${sumExpressions}
    FROM ${tableName}
    GROUP BY ${groupByColumn}
  `;

  const result = alasql(query);

  return result;
}

