 * @param {string} from_col - Column name containing values to replace with
 * @param {string} to_col - Column name containing values to replace missing values with
 * @param {string} [output_col='replaced'] - Name of the output column (default: 'replaced')
 * @returns {Object} A new tibble with the replaced values
 */
function replace_missing_with_other(data, from_col, to_col, output_col = 'replaced') {
    // Create a new column with the replacement values
    const replacement_values = select(data, to_col);

    // Create a new column with the original values (only where not NA)
    const original_values = select(data, from_col)
        .pipe(mutate({
            [from_col]: if_else(is_na(from_col), null, from_col)
        }));

    // Combine the columns and replace NAs
    return tibble({
        [output_col]: if_else(
            is_na(from_col),
            replacement_values[to_col],
            original_values[from_col]
        )
    })
    .pipe(mutate({
        // Keep all other columns from the original data
        ...Object.fromEntries(
            Object.keys(data).filter(col => col !== from_col && col !== to_col)
                .map(col => [col, data[col]])
        )
    }));
}

