```javascript
/**
 * Extracts human-readable decision rules from a trained decision tree
 * @param {Object} tree0 - The trained decision tree object from ml-cargo
 * @param {Array<string>} feature_names0 - List of feature names
 * @returns {Array<string>} Array of human-readable decision rules
 */
function extractDecisionRules(tree0, feature_names0) {
  const rules = [];

  /**
   * Recursively traverses the decision tree and generates rules
   * @param {Object} node - Current tree node
   * @param {Array<string>} conditions - Accumulated conditions for current path
   */
  function traverseTree(node, conditions = []) {
    // Check if this is a leaf node (terminal node with a prediction)
    if (node.isLeaf || node.output !== undefined) {
      // Construct the complete rule with all conditions
      const ruleConditions = conditions.length > 0 
        ? conditions.join(" AND ") 
        : "ROOT";
      const rule = `IF ${ruleConditions} THEN predict: ${node.output}`;
      rules.push(rule);
      return;
    }

    // Internal node - has a split
    if (node.split) {
      const featureName = feature_names0[node.split.featureIndex] || `Feature_${node.split.featureIndex}`;
      const threshold = node.split.value;

      // Left child: feature <= threshold
      if (node.left) {
        const leftCondition = `${featureName} <= ${threshold}`;
        traverseTree(node.left, [...conditions, leftCondition]);
      }

      // Right child: feature > threshold
      if (node.right) {
        const rightCondition = `${featureName} > ${threshold}`;
        traverseTree(node.right, [...conditions, rightCondition]);
      }
    }
  }

  // Start traversal from the root node
  traverseTree(tree0);

  return rules;
}

