function mergeColumnsWithPriority(baseTable, newColumns, priorityOrder) {
    // Create a shallow copy of the base table's columns
    const existingColumns = { ...baseTable.getColumns() };

    // Check if all priority columns exist in the new columns or already in the table
    priorityOrder.forEach(columnName => {
