        let sequenceIndex = 0;
        let currentListIndex = sequence[sequenceIndex];

        // Helper function to get the next value from the current list
        function getNextValue() {
            const currentList = lists[currentListIndex];

            // If we've exhausted the current list, move to the next in sequence
            if (currentList.isEmpty()) {
                sequenceIndex++;
                if (sequenceIndex >= sequence.length) {
                    // We've processed all elements in the sequence
                    self.end();
                    return;
