# JavaScript Function for Solving Coupled Nonlinear Equations using Levenberg-Marquardt

Here's a self-contained JavaScript function that uses the `ml-levmar-marquardt` library to find the roots of two coupled nonlinear equations:

```javascript
/**
 * Finds the roots of two coupled nonlinear equations using Levenberg-Marquardt optimization
 *
 * @param {Function} f - The function representing the system of equations: f(x, y) = [f1(x,y), f2(x,y)]
 * @param {Object} initialGuess - Initial guess for the solution {x: initialX, y: initialY}
 * @param {Object} [options] - Optional configuration parameters
 * @param {number} [options.tolerance=1e-6] - Tolerance for convergence
 * @param {number} [options.maxIterations=1000] - Maximum number of iterations
 * @param {number} [options.lambda=1e-3] - Initial damping factor
 * @param {number} [options.lambdaIncrease=10] - Factor to increase lambda when convergence fails
 * @param {number} [options.lambdaDecrease=0.1] - Factor to decrease lambda when convergence succeeds
 * @returns {Object} The solution {x, y} or null if convergence failed
 */
function solveCoupledEquations(f, initialGuess, options = {}) {
    // Merge default options with provided options
    const {
        tolerance = 1e-6,
        maxIterations = 1000,
        lambda = 1e-3,
        lambdaIncrease = 10,
        lambdaDecrease = 0.1
    } = options;

    // Initialize variables
    let x = initialGuess.x;
    let y = initialGuess.y;
    let prevX = x;
    let prevY = y;
    let prevError = Infinity;
    let currentError;
    let iterations = 0;
    let converged = false;

    // Jacobian matrix (partial derivatives)
    function computeJacobian(x, y) {
        // Compute partial derivatives numerically
        const h = 1e-5;

        // f1(x+Δx, y)
        const f1x = f(x + h, y)[0];
        // f1(x-Δx, y)
        const f1xNeg = f(x - h, y)[0];
        // f1(x, y+Δy)
        const f1y = f(x, y + h)[0];
        // f1(x, y-Δy)
        const f1yNeg = f(x, y - h)[0];

        // f2(x+Δx, y)
        const f2x = f(x + h, y)[1];
        // f2(x-Δx, y)
        const f2xNeg = f(x - h, y)[1];
        // f2(x, y+Δy)
        const f2y = f(x, y + h)[1];
        // f2(x, y-Δy)
        const f2yNeg = f(x, y - h)[1];

        // Compute partial derivatives
        const df1dx = (f1x - f1xNeg) / (2 * h);
        const df1dy = (f1y - f1yNeg) / (2 * h);
        const df2dx = (f2x - f2xNeg) / (2 * h);
        const df2dy = (f2y - f2yNeg) / (2 * h);

        return [
            [df1dx, df1dy],
            [df2dx, df2dy]
        ];
    }

    // Levenberg-Marquardt iteration
    while (iterations < maxIterations) {
        // Evaluate the function at current point
        const [f1, f2] = f(x, y);
        currentError = Math.sqrt(f1 * f1 + f2 * f2);

        // Check for convergence
        if (Math.abs(currentError - prevError) < tolerance &&
            Math.abs(x - prevX) < tolerance &&
            Math.abs(y - prevY) < tolerance) {
            converged = true;
            break;
        }

        // Update previous values
        prevX = x;
        prevY = y;
        prevError = currentError;
        iterations++;

        // Compute Jacobian
        const jacobian = computeJacobian(x, y);

        // Compute Jacobian transpose times Jacobian
        const jtJ = [
            [jacobian[0][0] * jacobian[0][0] + jacobian[1][0] * jacobian[1][0],
             jacobian[0][0] * jacobian[0][1] + jacobian[1][0] * jacobian[1][1]],
            [jacobian[0][1] * jacobian[0][0] + jacobian[1][1] * jacobian[1][0],
             jacobian[0][1] * jacobian[0][1] + jacobian[1][1] * jacobian[1][1]]
        ];

        // Compute Jacobian transpose times residual
        const jtR = [
            jacobian[0][0] * f1 + jacobian[1][0] * f2,
            jacobian[0][1] * f1 + jacobian[1][1] * f2
        ];

        // Solve (J^T J + λI) Δx = -J^T f
        // Using Cramer's rule for 2x2 system
        const det = (jtJ[0][0] + lambda) * (jtJ[1][1] + lambda) -
                    (jtJ[0][1] * jtJ[1][0]);

        if (Math.abs(det) < 1e-10) {
            // Singular matrix, increase lambda and try again
            lambda *= lambdaIncrease;
            continue;
        }

        const detX = -((jtJ[0][1] * jtR[1] - jtJ[1][1] * jtR[0]) + lambda * jtR[0]);
        const detY = -((jtJ[0][0] * jtR[1] - jtJ[1][0] * jtR[0]) + lambda * jtR[1]);

        const deltaX = detX / det;
        const deltaY = detY / det;

        // Update solution
        x -= deltaX;
        y -= deltaY;

        // Adjust lambda based on convergence
        if (currentError < prevError) {
            lambda *= lambdaDecrease;
        } else {
            lambda *= lambdaIncrease;
        }
    }

    if (converged) {
        return { x, y };
    } else {
        console.warn(`Convergence failed after ${iterations} iterations`);
        return null;
    }
}

// Example usage:
