const dfd = require("danfo-js-node");

function convertDateColumn(df) {
  /**
   * Converts the 'Date' column of a DataFrame to native date-time values
   * Parses each entry according to the "DD-MM-YYYY" pattern
   * 
   * @param {DataFrame} df - The input DataFrame with a 'Date' column
   * @returns {DataFrame} - DataFrame with converted Date column
   */

  // Extract the 'Date' column as an array
  const dateValues = df['Date'].values;

  // Convert each date string from DD-MM-YYYY to Date object
  const convertedDates = dateValues.map(dateStr => {
    if (dateStr === null || dateStr === undefined) {
      return null;
    }

    // Parse DD-MM-YYYY format
    const parts = dateStr.toString().split('-');
    const day = parseInt(parts[0], 10);
    const month = parseInt(parts[1], 10) - 1; // Month is 0-indexed
    const year = parseInt(parts[2], 10);

    // Create Date object
    const dateObj = new Date(year, month, day);

    // Validate the date
    if (isNaN(dateObj.getTime())) {
      console.warn(`Invalid date format: ${dateStr}`);
      return null;
    }

    return dateObj;
  });

  // Create a new Series with converted dates
  const dateSeries = new dfd.Series(convertedDates, { name: 'Date' });

  // Create a new DataFrame and replace the Date column
  const df_converted = df.copy();
  df_converted['Date'] = dateSeries;

  return df_converted;
}

