/**
 * Reorders elements of lst0 to follow the order defined by corresponding values in lst1
 * @param {Array} lst0 - The array of elements to reorder
 * @param {Array} lst1 - The array of values that define the desired order
 * @returns {Array} - A new array with elements from lst0 reordered according to lst1
 */
function reorderByCorrespondingValues(lst0, lst1) {
  // Create an array of objects pairing each element from lst0 with its corresponding value from lst1
  const paired = lst0.map((element, index) => ({
    element: element,
    orderValue: lst1[index]
  }));

