function fillMissingWithColumnMean(table) {
    if (!Array.isArray(table) || table.length === 0) {
        return table; // Return as is for empty tables
    }

    let numRows = table.length;
    let numCols = table[0].length;

    // Calculate mean for each column
    let columnMeans = Array(numCols).fill(0);
    let columnCounts = Array(numCols).fill(0);

    // Iterate through the table to compute means and counts
    for (let row of table) {
        for (let col = 0; col < numCols; col++) {
            if (row[col] !== null && row[col] !== undefined) { // Check for missing values
                columnMeans[col] += row[col];
                columnCounts[col]++;
            }
        }
    }

    // Compute the means
    for (let col = 0; col < numCols; col++) {
        if (columnCounts[col] > 0) {
            columnMeans[col] /= columnCounts[col];
        } else {
            columnMeans[col] = null; // No valid entries
        }
