            if (edge === 'patternIds') continue;
            const childState = currentState[edge];
            let failureState = currentState.failure || trie;
            while (failureState && !failureState[edge]) {
                failureState = failureState.failure;
            }
            childState.failure = failureState && failureState[edge] || trie;
            childState.patternIds = [...(childState.patternIds || []), ...(childState.failure.patternIds || [])];
            queue.push(childState);
