        }
        if (isNaN(floatA)) return 1; // b comes first
        if (isNaN(floatB)) return -1; // a comes first

        return floatA - floatB;
    });

    // Copy the sorted values back to the original list
    for (let i = 0; i < list.length; i++) {
        list[i] = sortedList[i];
    }

    return list;
}

