# K-Means Clustering Function

```javascript
const KMeans = require('ml-kmeans');

/**
 * Partitions a one-dimensional array into k clusters using k-means algorithm
 * @param {number[]} arr0 - Input array of numbers to be clustered
 * @param {number} k - Number of clusters to create
 * @param {Object} options - Optional configuration object
 * @param {number} options.maxIterations - Maximum number of iterations (default: 100)
 * @param {number} options.seed - Random seed for reproducibility (default: undefined)
 * @returns {number[]} Array of cluster labels (0 to k-1) for each element
 */
function kMeansClustering(arr0, k, options = {}) {
  // Validate inputs
  if (!Array.isArray(arr0) || arr0.length === 0) {
    throw new Error('Input array must be a non-empty array');
  }

  if (!Number.isInteger(k) || k < 1) {
    throw new Error('Number of clusters must be a positive integer');
  }

  if (k > arr0.length) {
    throw new Error('Number of clusters cannot exceed the number of data points');
  }

  // Convert 1D array to 2D format required by ml-kmeans
  // Each data point is a [value] array
  const data = arr0.map(value => [value]);

  // Set default options
  const kmOptions = {
    maxIterations: options.maxIterations || 100,
    seed: options.seed !== undefined ? options.seed : Math.random()
  };

  // Run k-means clustering
  const result = KMeans(data, k, kmOptions);

  // Extract and return cluster labels
  return result.clusters;
}

