 * Transform a two-dimensional dataset into a dictionary according to orientation
 * @param {Array<Array>} df0 - Two-dimensional dataset (rows x columns)
 * @param {string} var0 - Orientation mode ('rows', 'columns', or 'records')
 * @returns {Object} Transformed dictionary
 */
function transformDataset(df0, var0) {
  if (!Array.isArray(df0) || df0.length === 0) {
    console.error('Invalid dataset: must be a non-empty array');
    return {};
  }

  const result = {};

  switch (var0.toLowerCase()) {
    case 'rows':
      // Transform by rows: each row becomes a key-value pair
      df0.forEach((row, index) => {
        const key = row[0] !== undefined ? row[0] : `row_${index}`;
        result[key] = row.slice(1);
      });
      break;

    case 'columns':
      // Transform by columns: each column becomes a key-value pair
      if (Array.isArray(df0[0])) {
        const numColumns = df0[0].length;
        for (let colIndex = 0; colIndex < numColumns; colIndex++) {
          const columnKey = `col_${colIndex}`;
          result[columnKey] = df0.map(row => row[colIndex]);
        }
      }
      break;

    case 'records':
      // Transform into array of record objects
      if (Array.isArray(df0[0])) {
        const headers = df0[0];
        df0.slice(1).forEach((row, index) => {
          const record = {};
          headers.forEach((header, colIndex) => {
