function rankElements(lst0) {
  // Create an array of [value, originalIndex] pairs
  const indexed = lst0.map((value, index) => ({ value, index }));

  // Sort by value to determine ranks
  const sorted = indexed.sort((a, b) => a.value - b.value);

  // Create a map of originalIndex -> rank
  const rankMap = new Map();
  sorted.forEach((item, rank) => {
