 * @param {number} index - The position within each sequence to sort by
 * @param {boolean} [ascending=true] - Sort direction (true for ascending, false for descending)
 * @returns {Object} - New object with entries sorted by the element at the specified index
 */
function sortMappingBySequenceIndex(mapping, index, ascending = true) {
