/**
 * Encodes categorical values in a column to unique integer indices
 * @param {Object} df0 - The input data table (similar to a pandas DataFrame)
 * @param {string} colName - Name of the categorical column to encode
 * @returns {Object} A new data table with the encoded column
 */
function encodeCategoricalColumn(df0, colName) {
    // Import required scikit-learnjs components
    const { LabelEncoder } = require('sklearnjs/preprocessing/label');

    // Create a LabelEncoder instance
    const encoder = new LabelEncoder();

    // Get the unique values from the column
