    // Fit the encoder on the unique values
    encoder.fit(uniqueValues);

    // Transform the column values
    const encodedValues = df0[colName].map(value => {
        return encoder.transform(value.toString());
    });

    // Create a copy of the original data table
    const result = {...df0};

    // Replace the original column with encoded values
    result[colName] = encodedValues;

    return result;
}

